"""Collect results/*.json into results/SUMMARY.md (manuscript value vs. this code)."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from forcecal.data import RESULTS_DIR

J = {k: json.loads((RESULTS_DIR / f"{k}.json").read_text())
     for k in ("quasi_static", "dynamic_poly", "dynamic_mlp", "noise")}


def f(x, n=4):
    return f"{x:.{n}f}"


def main():
    qs, dp, mlp, nz = J["quasi_static"], J["dynamic_poly"], J["dynamic_mlp"], J["noise"]
    L = ["# Results summary", "",
         "Generated by `scripts/06_summary.py`. MAE/RMSE marked *all6* average all six wrench components "
         "(N and N·m), as in the manuscript; *force* = Fx, Fy, Fz only [N]. "
         "All targets are the Simulink-filtered wrench unless marked *vs raw*.", ""]

    q, qb = qs["test"], qs["benchmark"]
    L += ["## Quasi-static (scripts/01_quasi_static.py)", "",
          f"Split: {qs['split']} -> {qs['n_train']} train / {qs['n_test']} test; benchmark {qs['n_benchmark']} poses. "
          f"Degree 3, {qs['n_terms_per_output']} terms per output.", "",
          "| Metric | Manuscript | This code |", "|---|---|---|",
          f"| Test MSE (all6) | 0.005 N² | {f(q['all6_mse'], 6)} |",
          f"| Bench MAE (all6) | 0.021 N | {f(qb['all6_mae'])} |",
          f"| Bench RMSE (all6) | 0.036 N | {f(qb['all6_rmse'])} |",
          f"| Bench RMSE (force) | – | {f(qb['force_rmse'])} N |",
          f"| Bench max abs X / Y / Z | 0.13 / 0.06 / 0.11 N | {f(qb['Fx_max_abs'], 3)} / {f(qb['Fy_max_abs'], 3)} / {f(qb['Fz_max_abs'], 3)} N |",
          f"| Bench torque RMSE Tx / Ty / Tz | – | {f(qb['Tx_rmse'], 5)} / {f(qb['Ty_rmse'], 5)} / {f(qb['Tz_rmse'], 5)} N·m |",
          "", "Degree sweep:", "",
          "| Degree | Test MSE (all6) | Bench RMSE (all6) | Bench RMSE (force) | 5-fold CV RMSE (force) |", "|---|---|---|---|---|"]
    for d, r in qs["degree_sweep"].items():
        L.append(f"| {d} | {f(r['test']['all6_mse'], 5)} | {f(r['benchmark']['all6_rmse'])} | "
                 f"{f(r['benchmark']['force_rmse'])} | {f(r['cv5']['force_rmse'])} |")
    L += ["", "Joint-angle input (held-out test only; the benchmark log has no joint angles):", "",
          "| Degree | Test RMSE (all6) | Test RMSE (force) |", "|---|---|---|"]
    for d, r in qs["joint_angle_model"].items():
        L.append(f"| {d} | {f(r['test']['all6_rmse'])} | {f(r['test']['force_rmse'])} |")
    L.append(f"| RPY model, degree 3 (reference) | {f(q['all6_rmse'])} | {f(q['force_rmse'])} |")

    t, b = dp["final"]["test"], dp["final"]["benchmark"]
    L += ["", "## Dynamic polynomial (scripts/02_dynamic_poly.py)", "",
          f"Pool {'+'.join(dp['train_pool'])} ({dp['n_pool']} samples), {dp['split']}; benchmark {dp['benchmark']} "
          f"({dp['n_benchmark']} samples). Degree 2, {dp['n_features']} features + intercept per output.", "",
          "| Metric | Manuscript | This code |", "|---|---|---|",
          f"| Test MAE / RMSE (all6) | 0.027 / 0.053 N | {f(t['all6_mae'])} / {f(t['all6_rmse'])} |",
          f"| Bench MAE / RMSE (all6) | 0.021 / 0.045 (0.0458) N | {f(b['all6_mae'])} / {f(b['all6_rmse'])} |",
          f"| Bench RMSE (force) | – | {f(b['force_rmse'])} N |",
          f"| Bench max abs X / Y / Z | 0.42 / 0.40 / 0.26 N | {f(b['Fx_max_abs'], 3)} / {f(b['Fy_max_abs'], 3)} / {f(b['Fz_max_abs'], 3)} N |",
          f"| Bench max force magnitude | 0.54 N (0.108 % FSO) | {f(b['force_max_magnitude'], 3)} N ({f(b['force_max_magnitude_pct_fso'], 3)} %) |",
          f"| Bench torque RMSE | – | {f(b['torque_rmse'], 5)} N·m |",
          f"| Bench force RMSE vs raw signal | – | {f(dp['final']['benchmark_vs_raw']['force_rmse'])} N |",
          "", "| Degree | Test RMSE (all6) | Bench RMSE (all6) |", "|---|---|---|"]
    for d, r in dp["degree_sweep"].items():
        L.append(f"| {d} | {f(r['test']['all6_rmse'])} | {f(r['benchmark']['all6_rmse'])} |")
    qb0 = dp["qs_only_baseline"]["benchmark"]
    L += ["", "Quasi-static-only baseline vs. two-stage (benchmark):", "",
          "| | Force RMSE | Max force magnitude | Torque RMSE |", "|---|---|---|---|",
          f"| QS only (dynamic offset = 0) | {f(qb0['force_rmse'])} N | {f(qb0['force_max_magnitude'], 3)} N | {f(qb0['torque_rmse'], 5)} N·m |",
          f"| QS + polynomial | {f(b['force_rmse'])} N | {f(b['force_max_magnitude'], 3)} N | {f(b['torque_rmse'], 5)} N·m |"]
    m = mlp["summary_over_seeds"]["benchmark"]
    L.append(f"| QS + MLP (mean over seeds) | {f(m['force_rmse']['mean'])} N | {f(m['force_max_magnitude']['mean'], 3)} N | {f(m['torque_rmse']['mean'], 5)} N·m |")
    c = dp["conditioning"]
    L += ["", f"Conditioning: cond(design) standardized {c['cond_design_standardized']:.3g}, unscaled {c['cond_design_unscaled']:.3g}. "
          f"Unscaled OLS bench RMSE {f(dp['unscaled_ols']['benchmark']['all6_rmse'])}.", "",
          "| Ridge alpha | Test RMSE (all6) | Bench RMSE (all6) |", "|---|---|---|"]
    for a, r in dp["ridge"].items():
        if isinstance(r, dict):
            L.append(f"| {a} | {f(r['test']['all6_rmse'])} | {f(r['benchmark']['all6_rmse'])} |")
    L += ["", "Recording-level evaluation (no samples shared between training and test):", "",
          "| Setting | Test RMSE (all6) | Bench RMSE (all6) |", "|---|---|---|"]
    for k, r in dp["recording_level"].items():
        L.append(f"| {k} | {f(r['test']['all6_rmse'])} | {f(r['benchmark']['all6_rmse'])} |")

    s = mlp["summary_over_seeds"]
    L += ["", "## Dynamic MLP (scripts/03_dynamic_mlp.py)", "",
          f"{mlp['n_parameters']} parameters, {mlp['epochs']} epochs, seeds {mlp['seeds']} (mean ± std). Same split and benchmark as the polynomial model.", "",
          "| Metric | Manuscript | This code |", "|---|---|---|"]
    for name, key, paper in (("Test MAE (all6)", ("test", "all6_mae"), "0.021 N"),
                             ("Test RMSE (all6)", ("test", "all6_rmse"), "0.041 N"),
                             ("Bench MAE (all6)", ("benchmark", "all6_mae"), "0.026 N"),
                             ("Bench RMSE (all6)", ("benchmark", "all6_rmse"), "0.049 N"),
                             ("Bench RMSE (force)", ("benchmark", "force_rmse"), "–"),
                             ("Bench max abs X", ("benchmark", "Fx_max_abs"), "0.44 N"),
                             ("Bench max abs Y", ("benchmark", "Fy_max_abs"), "0.41 N"),
                             ("Bench max abs Z", ("benchmark", "Fz_max_abs"), "0.26 N"),
                             ("Bench max force magnitude", ("benchmark", "force_max_magnitude"), "0.53 N (0.106 % FSO)"),
                             ("Bench torque RMSE", ("benchmark", "torque_rmse"), "–"),
                             ("Bench force RMSE vs raw signal", ("benchmark_vs_raw", "force_rmse"), "–")):
        v = s[key[0]][key[1]]
        L.append(f"| {name} | {paper} | {f(v['mean'])} ± {f(v['std'])} |")
    L += ["", "| Recording-level (seed %d) | Test RMSE (all6) | Bench RMSE (all6) |" % mlp["main_seed"], "|---|---|---|"]
    for k, r in mlp["recording_level"].items():
        L.append(f"| {k} | {f(r['test']['all6_rmse'])} | {f(r['benchmark']['all6_rmse'])} |")
    lat = mlp["latency"]
    L += ["", f"CPU inference latency ({lat['cpu']}, torch {lat['torch']}, {lat['torch_threads']} threads, incl. input scaling): "
          f"batch 1 median {lat['batch1_median_us']:.0f} µs, batch 64 median {lat['batch64_median_us']:.0f} µs."]

    L += ["", "## Noise (scripts/05_noise.py)", "", "| Quantity | Fx | Fy | Fz |", "|---|---|---|---|"]

    def row(name, d):
        return f"| {name} | {f(d['Fx'], 3)} | {f(d['Fy'], 3)} | {f(d['Fz'], 3)} |"
    L.append(row("QS poses: RMS(raw − filtered)", nz["qs"]["train_poses"]["rms_raw_minus_filtered"]))
    for k, v in nz["dynamic"].items():
        L.append(row(f"Dynamic {k}: RMS(raw − filtered), all frames", v["rms_raw_minus_filtered"]))
        L.append(row(f"Dynamic {k}: RMS(raw − filtered), 5 % lowest acceleration", v["low_accel_5pct"]["rms_raw_minus_filtered"]))

    out = RESULTS_DIR / "SUMMARY.md"
    out.write_text("\n".join(L) + "\n")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
